missing = []
copied = 0

for r in records:
    src = SOURCE / r["source_filename"]
    folder = DEST / r["target_folder"]
    folder.mkdir(parents=True, exist_ok=True)
    dst = folder / r["source_filename"]

    if not src.exists():
        missing.append(r["source_filename"])
        continue

    shutil.copy2(src, dst)
    copied += 1

print(f"Copied: {copied}/{len(records)}")

if missing:
    print("\nMISSING FILES:")
    for name in missing:
        print(name)
    raise SystemExit(1)

